// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address nftContract, uint256 tokenId, bytes calldata data) public {
        // Ensure caller is not address(c) and not address(0)
        vm.assume(caller != address(c));
        vm.assume(caller != address(0));
        // Ensure caller can actually send a tx
        vm.deal(caller, 0);

        // Call onERC721Received on c
        bytes4 ret;
        vm.prank(caller);
        (bool success, bytes memory retData) = address(c).call(
            abi.encodeWithSignature("onERC721Received(address,address,uint256,bytes)", caller, nftContract, tokenId, data)
        );
        require(success, "call failed");
        ret = abi.decode(retData, (bytes4));

        // The correct implementation must return ERC721TokenReceiver.onERC721Received.selector (0x150b7a02)
        assertTrue(ret == bytes4(0x150b7a02));
    }
}

