pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address baseToken) public {
        // bound to a valid address that is not address(this) to see the difference
        vm.assume(baseToken != address(0));
        vm.assume(baseToken != address(this));
        // The other parameters of initialize can be arbitrary; we choose safe defaults
        c.initialize(
            baseToken,
            address(0),
            1,
            1,
            1,
            0,
            bytes32(0),
            false,
            false
        );
        // After initialization, baseToken() must equal the passed baseToken argument.
        // The bug reassigns baseToken to address(this), breaking this equality.
        assertTrue(c.baseToken() == baseToken);
    }
}

